// Generates invite codes into a file you name. The real launch codes are generated by the team, never committed.
//   bun run scripts/invites/generate.ts <output-file> [--count 100]
// One code per line (XXXX-XXXX-XXXX), mode 0600, refuses to overwrite and refuses a path inside this repository.
// Load them into the database with scripts/invites/import.ts. Nothing here touches the database or the network.
import { existsSync, writeFileSync } from "node:fs";
import { relative, resolve } from "node:path";
import { generateInviteCode } from "../../src/lib/invite-code";
import { flag, positional } from "./db";

const [target] = positional();
if (!target) {
  console.error("usage: bun run scripts/invites/generate.ts <output-file> [--count 100]");
  process.exit(2);
}
const count = Number(flag("count") ?? "100");
if (!Number.isInteger(count) || count < 1 || count > 10_000) {
  console.error("--count must be a whole number from 1 to 10000.");
  process.exit(2);
}
const out = resolve(target);
const repoRoot = resolve(import.meta.dir, "../../..");
const rel = relative(repoRoot, out);
if (!rel.startsWith("..") && !rel.startsWith("/")) {
  console.error("Refusing to write codes inside the repository. Pick a private path outside it.");
  process.exit(2);
}
if (existsSync(out)) {
  console.error("Refusing to overwrite an existing file.");
  process.exit(2);
}
const codes = new Set<string>();
while (codes.size < count) codes.add(generateInviteCode());
writeFileSync(out, [...codes].join("\n") + "\n", { mode: 0o600, flag: "wx" });
console.log(`Wrote ${codes.size} codes to ${out} (mode 600). Codes are not printed.`);
